    rows = _conn.execute(
        "SELECT lower(substr(email, instr(email, '@') + 1)) AS domain, COUNT(*) AS count "
        "FROM users GROUP BY domain"
    ).fetchall()
    return {row["domain"]: row["count"] for row in rows}
"}

